import {ARCHIVE_PACK,ARCHIVE_PAGES,ARCHIVE_TASKS,ARCHIVE_TEXT_LIMIT,ARCHIVE_SOURCES,ARCHIVE_EVENTS,ARCHIVE_SITES,ARCHIVE_MAP_CARDS,ARCHIVE_QUESTIONS,ARCHIVE_REPLY_FIELDS,archiveSourceById,archiveQuestionById} from './travelers-archive-content.mjs';
import {travelersArchive,recoverTravelersArchive,setArchivePage,setArchiveTask,setArchiveQuestion,setArchiveSource,setArchiveDetail,setArchiveMap,checkArchiveMap,setArchiveOrder,moveArchiveEvent,checkArchiveOrder,answerArchiveQuestion,setArchiveReplyChoice,setArchiveReplyText,checkArchiveReply,keepArchiveReply,useArchiveSupport,noteArchiveSources,setArchiveReading,revisitArchive} from './travelers-archive-core.mjs';
import {archiveParcelArt,archivePlaceMap,archiveDateCard} from './travelers-archive-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pageLabels={'parcel':'Open the parcel','place-dates':'Place and dates','sources':'Look at the sources','reply':'Prepare a reply'};
const taskLabels={map:'Place the evidence',order:'Order the dates',claims:'Look closely','source-choice':'Choose a source',limits:'Ask what we know'};
const btn=(attr,value,label,selected=false,kind='secondary')=>`<button type="button" class="${kind}${selected?' selected':''}" data-ta-${attr}="${esc(value)}" aria-pressed="${selected}">${esc(label)}</button>`;
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
const last=(s,task)=>s.checks.findLast(c=>c.task===task);
const currentQuestion=s=>ARCHIVE_QUESTIONS.find(q=>q.id===s.question&&q.task===s.task)||ARCHIVE_QUESTIONS.find(q=>q.task===s.task)||ARCHIVE_QUESTIONS[0];
const effectiveTask=s=>s.page==='place-dates'?(s.task==='order'?'order':'map'):s.page==='sources'?(ARCHIVE_QUESTIONS.some(q=>q.task===s.task)?s.task:'claims'):'reply';
function narration(text,task,label='Hear this part'){return `<span data-ta-audio="${esc(task)}">${hearButton(text,label)}</span>`;}
const same=(a,b)=>a===b||(Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>same(v,b[i])))||(a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(a)&&!Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&same(a[k],b[k])));
const earlierLabel=(record,response)=>`<p class="ta-earlier-check" data-ta-earlier-check ${same(record.response,response)?'hidden':''}><strong>Earlier check.</strong> These comments refer to an earlier draft. Compare again when you want feedback on this draft.</p>`;
function feedback(record,id,response){if(!record)return '';return `<div class="ta-feedback" id="${id}" role="status" tabindex="-1">${earlierLabel(record,response)}${esc(record.feedback.feedback)}</div>`;}
function photoPanel(s){const p=archiveSourceById('photo'),detail=s.detail==='boats'?'Boats detail':s.detail==='buildings'?'Buildings detail':'Whole photograph';return `<section class="ta-source-sheet" data-ta-source-visible="photo" aria-label="Historical photograph"><h3>A view at one quay</h3><figure class="ta-photo"><div class="ta-image-window ta-image-${esc(s.detail)}"><img src="${esc(p.image.src)}" width="2769" height="2160" loading="lazy" decoding="async" alt="${esc(p.image.alt)}"></div><figcaption><strong>${esc(detail)}</strong>${s.detail==='whole'?'':'. Magnified view of the same image; return to the whole photograph to compare.'}<br>${esc(p.image.credit)}. ${link(p.url,'Museum record')} · ${link(p.image.licenseUrl,'CC0 licence')}</figcaption></figure><div class="ta-photo-tools" role="group" aria-label="Photograph view">${btn('detail','whole','Whole image',s.detail==='whole')}${btn('detail','boats','Look at boats',s.detail==='boats')}${btn('detail','buildings','Look at buildings',s.detail==='buildings')}</div><p class="ta-source-date"><strong>Photo object:</strong> museum production date 29 January 1910.<br><strong>Scene:</strong> January flood; exact capture moment not established here.</p><details><summary>Who made this? What does its date mean?</summary><p>Creator attribution: ${esc(p.creator)}. ${esc(p.creatorNotice)}</p><p>${esc(p.dateNotice)}</p><p>${esc(p.image.reproduction)} ${esc(p.image.rightsReceipt)}</p></details>${narration('This is one photograph at the Quai des Grands-Augustins. Its museum production date is 29 January 1910, but that alone does not fix the exact moment pictured. We can look for boats, water and buildings. It cannot show the whole city or everyone’s feelings.','global','Hear the photo label')}</section>`;}
function chronologyPanel(){const p=archiveSourceById('chronology');return `<section class="ta-source-sheet" data-ta-source-visible="chronology" aria-label="Modern chronology"><h3>The archive’s date cards</h3><p class="ta-modern-label">Original modern summaries based on Archives de Paris</p><ol class="ta-source-events">${ARCHIVE_EVENTS.map(e=>`<li>${archiveDateCard(e)}<p>${esc(e.text)}</p></li>`).join('')}</ol><p class="ta-source-date"><strong>Document:</strong> modern educational chronology. Its exact publication date is not stated.</p><p>${link(p.url,'Archives de Paris source page')}</p><details><summary>What can this source tell us?</summary><p>${esc(p.summary)}</p><p>${esc(p.reuseNotice)} The return to the riverbed does not date every street drying.</p>${link(p.document,'Read the official chronology PDF')}</details>${narration(ARCHIVE_EVENTS.map(e=>`${e.dateLabel}. ${e.text}`).join(' ')+' These are original modern summaries. The exact publication date of the archive’s teaching chronology is not stated.','global','Hear the date cards')}</section>`;}
function sourceSwitcher(s){return `<div class="ta-source-tabs" role="group" aria-label="Choose a source to inspect">${btn('source','photo','Photograph',s.source==='photo')}${btn('source','chronology','Date cards',s.source==='chronology')}</div>${s.source==='photo'?photoPanel(s):chronologyPanel()}`;}
function mapTask(s){return `<div class="ta-source-tabs" role="group" aria-label="Choose a map card">${btn('source','photo','Photo card',s.source==='photo')}${btn('source','chronology','Highest-mark card',s.source==='chronology')}</div><div class="ta-map-cards">${ARCHIVE_MAP_CARDS.filter(c=>c.id===(s.source==='chronology'?'gauge':'photo')).map(c=>`<section class="ta-map-choice"><h3>${esc(c.label)}</h3><p>${esc(c.prompt)}</p><div class="ta-options">${ARCHIVE_SITES.map(site=>btn('map',`${c.id}:${site.id}`,site.label,s.map[c.id]===site.id)).join('')}</div><button class="secondary" type="button" data-ta-map-check="${c.id}">Compare this place label</button>${feedback(last(s,`map-${c.id}`),`ta-map-feedback-${c.id}`,{cardId:c.id,siteId:s.map[c.id]})}</section>`).join('')}</div><p class="ta-small">A camera marks where the photo was taken, not where the museum is. Our schematic cannot tell us flood extent or a route.</p>`;}
function orderTask(s){return `<p>Select a card to add it to your order. Use the movement buttons to change it.</p><div class="ta-order-pool">${ARCHIVE_EVENTS.filter(e=>!s.order.includes(e.id)).map(e=>`<button type="button" class="secondary ta-event-pick" data-ta-order-add="${e.id}">${archiveDateCard(e)}<span>Add to my order</span></button>`).join('')||'<p>All three cards are in your draft. You can still move or remove them.</p>'}</div><ol class="ta-draft-order" tabindex="-1" aria-label="Your draft date order">${s.order.map((id,i)=>{const e=ARCHIVE_EVENTS.find(e=>e.id===id);return `<li>${archiveDateCard(e)}<div class="ta-order-controls"><button type="button" class="secondary" data-ta-move="${id}:-1" ${i===0?'disabled':''} aria-label="Move ${esc(e.title)} earlier">Earlier</button><button type="button" class="secondary" data-ta-move="${id}:1" ${i===s.order.length-1?'disabled':''} aria-label="Move ${esc(e.title)} later">Later</button><button type="button" class="text-button" data-ta-order-remove="${id}" aria-label="Remove ${esc(e.title)} from your order">Remove</button></div></li>`;}).join('')||'<li class="ta-empty-order">Your order can start with any card.</li>'}</ol><p class="ta-small">${esc(ARCHIVE_PACK.timelineNotice)}</p><button class="primary" type="button" data-ta-order-check>Compare my date order</button>${feedback(last(s,'order'),'ta-order-feedback',{order:s.order})}`;}
function questionTask(s){const group=effectiveTask(s),qs=ARCHIVE_QUESTIONS.filter(q=>q.task===group),q=qs.find(q=>q.id===s.question)||qs[0],record=last(s,q.id);return `<p class="ta-question-reminder">${esc(q.prompt)}</p>${narration(q.prompt,q.id,'Hear this question')}${q.task==='claims'&&s.source==='photo'&&s.detail!=='whole'?`<p>${btn('detail','whole','Return to the whole photograph for this question')}</p>`:''}<div class="ta-options">${q.choices.map(c=>btn('answer',`${q.id}:${c.id}`,c.label,s.answers[q.id]===c.id)).join('')}</div>${feedback(record,`ta-answer-feedback-${q.id}`,{questionId:q.id,choice:s.answers[q.id]})}<p class="ta-small">Use the source beside this question. You can change your answer or keep looking.</p>`;}
function replyTask(s){const record=last(s,'reply'),r=s.reply;return `<p class="ta-question-reminder"><strong>Our reader asks:</strong> ${esc(ARCHIVE_PACK.question)}</p>${ARCHIVE_REPLY_FIELDS.map(f=>`<fieldset class="ta-reply-field"><legend>${esc(f.label)}</legend><div class="ta-options">${f.choices.map(c=>btn('reply-choice',`${f.id}:${c.id}`,c.label,r[f.id]===c.id)).join('')}${btn('reply-choice',`${f.id}:clear`,'Leave this undecided',r[f.id]===null)}</div></fieldset>`).join('')}<button class="secondary" type="button" data-ta-reply-check>Think about my evidence cards</button>${record?`<div class="ta-feedback" id="ta-reply-feedback" role="status" tabindex="-1">${earlierLabel(record,r)}${['claim','evidence','limit'].map(id=>`<p><strong>${esc(ARCHIVE_REPLY_FIELDS.find(f=>f.id===id).label)}:</strong> ${esc(record.feedback[id].feedback)}</p>`).join('')}<p>${esc(record.feedback.originalText)}</p></div>`:''}<label class="ta-writing-label" for="ta-reply-text">My own words, if I want to write</label><p class="ta-small" id="ta-writing-help">Or tell someone aloud. A human can read this with you; the game does not grade your words. Up to ${ARCHIVE_TEXT_LIMIT.toLocaleString('en-US')} characters, saved only on this device.</p><textarea id="ta-reply-text" rows="6" aria-describedby="ta-writing-help ta-writing-count ta-writing-error">
${esc(r.text)}</textarea><p class="ta-small" id="ta-writing-count" aria-live="polite">${Array.from(r.text).length} / ${ARCHIVE_TEXT_LIMIT} characters</p><p id="ta-writing-error" role="status"></p><span data-ta-audio="reply">${hearButton(r.text||'Your own words are optional. You can also tell someone aloud.','Hear my words')}</span><button class="primary" type="button" data-ta-keep>Keep my reply draft</button><p id="ta-kept-status" role="status" tabindex="-1">${s.kept?'A reply draft is kept. Keeping again replaces that snapshot with this draft.':'An unfinished or uncertain draft is welcome.'}</p>${s.kept?`<details><summary>See my kept draft</summary><p>${esc(ARCHIVE_REPLY_FIELDS[0].choices.find(c=>c.id===s.kept.reply.claim)?.label||'Claim undecided')}<br>${esc(ARCHIVE_REPLY_FIELDS[1].choices.find(c=>c.id===s.kept.reply.evidence)?.label||'Evidence undecided')}</p><blockquote class="ta-own-writing">${esc(s.kept.reply.text||'No original words were added.')}</blockquote><p class="ta-small">Kept locally with source labels and support. These words were not automatically checked.</p></details>`:''}<p><a href="#paris">Return to Paris</a> · <a href="#post">Visit the Post Office</a> · <a href="#loft">Tell a new fictional story</a></p><p class="ta-small">A story inspired by this visit is fiction. Your reply is not sent or inserted into an existing delivery.</p>`;}
function supportPanel(s,task){const supports={...s.support.global,...s.support[task]},help=task==='order'?'Read the month as well as the day: January, then February, then March. The spaces on this strip do not measure time.':task.startsWith('map-')?'Read the place printed on the source, then find that name in the legend. A symbol has a particular job.':task==='reply'?'Use a claim, the source that supports it, and something that source cannot tell us. The date cards answer the timing question; a photo adds one local view.':'Ask what is visible, what comes from a source label, and what remains unknown. A picture’s production date is not automatically the exact time of its scene.',example='Different example: an original modern drawing of a closed shop shows its door in that drawing. It does not tell us what the shopkeeper was thinking, or prove the shop stayed closed for a month.';return `<aside class="ta-support" tabindex="-1"><div class="ta-support-buttons">${btn('support','help','A thinking clue')}${btn('support','example','A different example')}${btn('support','together',supports.together?'Working together is kept':'We’re working together',!!supports.together)}</div>${supports.help?`<p id="ta-help" tabindex="-1">${esc(help)}</p>`:''}${supports.example?`<p id="ta-example" tabindex="-1">${esc(example)}</p>`:''}<details><summary>How did we read this visit?</summary><p class="ta-small">This is a separate report, not a reading assessment.</p><div class="ta-support-buttons">${[['unobserved','Reading not observed'],['together','Read together'],['reported-independent','Reported read independently']].map(([id,l])=>btn('reading',id,l,s.reading===id)).join('')}</div></details></aside>`;}
export function travelersArchiveEntry(){return '<aside class="ta-entry"><div><h2>A parcel from another time</h2><p>Explore a real photograph, compare dates and prepare a careful reply for a fictional reader.</p></div><a class="secondary" href="#archive">Open Travelers’ Archive</a></aside>';}
export function travelersArchivePage(state){const s=travelersArchive(state);if(!s)return '<section class="ta-workspace ta-unavailable"><h1 id="ta-title" tabindex="-1">An earlier archive draft is kept</h1><p>This format cannot be opened here. Its exact work remains available in notes downloads.</p><button class="secondary" type="button" data-ta-recover>Keep the earlier record and start fresh</button><p><a href="#notes">Grown-up notes</a></p></section>';let main,task='global';if(s.page==='parcel')main=`<section class="ta-parcel"><h2 id="ta-title" tabindex="-1">A picture. A question.</h2>${archiveParcelArt()}<p>${esc(ARCHIVE_PACK.story)}</p><p class="ta-reader-question">${esc(ARCHIVE_PACK.question)}</p><p class="ta-small">${esc(ARCHIVE_PACK.notice)}</p>${narration(ARCHIVE_PACK.story+' '+ARCHIVE_PACK.question,'global','Hear the parcel invitation')}<p>${btn('page','place-dates','Explore the place and dates',false,'primary')}</p></section>`;
 else if(s.page==='place-dates'){const t=effectiveTask(s);task=t==='order'?'order':s.source==='chronology'?'map-gauge':'map-photo';main=`<h2 id="ta-title" tabindex="-1">${t==='order'?'What happened earlier and later?':'Where does this evidence belong?'}</h2><div class="ta-task-tabs" role="group" aria-label="Place and date investigations">${['map','order'].map(id=>btn('task',id,taskLabels[id],t===id)).join('')}</div><div class="ta-layout"><aside>${t==='map'?`${archivePlaceMap()}<p class="ta-source-date" data-ta-source-visible="photo chronology"><strong>Photo label:</strong> Quai des Grands-Augustins.<br><strong>Highest-mark card:</strong> Austerlitz measuring scale.</p><p class="ta-small">${esc(ARCHIVE_PACK.mapNotice)}</p>`:chronologyPanel()}</aside><section class="ta-task-slip">${t==='map'?mapTask(s):orderTask(s)}</section></div>`;}
 else if(s.page==='sources'){const t=effectiveTask(s),q=currentQuestion({...s,task:t});task=q.id;main=`<h2 id="ta-title" tabindex="-1">What can these sources tell us?</h2><div class="ta-task-tabs" role="group" aria-label="Source investigations">${['claims','source-choice','limits'].map(id=>btn('task',id,taskLabels[id],t===id)).join('')}</div><div class="ta-question-tabs" role="group" aria-label="Questions in this investigation">${ARCHIVE_QUESTIONS.filter(x=>x.task===t).map((x,i)=>btn('question',x.id,`Question ${i+1}`,x.id===q.id)).join('')}</div><h3 id="ta-current-question" class="ta-turn-question" tabindex="-1">${esc(q.prompt)}</h3><div class="ta-layout"><aside>${sourceSwitcher(s)}</aside><section class="ta-task-slip">${questionTask({...s,task:t})}</section></div><p class="ta-small">${esc(ARCHIVE_PACK.sourceNotice)}</p>`;}
 else{task='reply';main=`<h2 id="ta-title" tabindex="-1">A careful reply can leave room for questions</h2><p class="ta-reader-question"><strong>Our fictional reader asks:</strong> ${esc(ARCHIVE_PACK.question)}</p><div class="ta-layout"><aside>${chronologyPanel()}<details data-ta-extra-source="photo"><summary>Compare the photograph again</summary><p>${btn('page','sources','Look at the sources again')}</p><p>${esc(archiveSourceById('photo').summary)}</p></details></aside><section class="ta-task-slip">${replyTask(s)}</section></div>`;}
 return `<div class="ta-workspace" data-ta-active-task="${esc(task)}"><header><a class="back" href="#paris">Back to Paris</a><h1>Travelers’ Archive</h1><p>Paris and the Seine flood, 1910</p></header><nav class="ta-pages" aria-label="Archive pages">${ARCHIVE_PAGES.map((id,i)=>btn('page',id,`${i+1}. ${pageLabels[id]}`,s.page===id)).join('')}</nav>${main}${supportPanel(s,task)}<footer><button class="text-button" type="button" data-ta-revisit>Keep exploring this visit</button><a href="#home">Take a break in the garden</a><a href="#notes">Grown-up notes</a></footer></div>`;}
export function bindTravelersArchive(state,ctx){const root=document.querySelector('.ta-workspace');if(!root)return;const focus=selector=>ctx.focus?.(selector),save=()=>ctx.save?.(),redraw=(selector='#ta-title')=>{save();ctx.render();focus(selector);};
 let writingDirty=false,writingError='';
 // Browser textarea parsing can normalize line endings. Only a real input event may replace exact imported words.
 const validWriting=()=>{if(!writingDirty)return true;const error=root.querySelector('#ta-writing-error');if(error)error.textContent=writingError;focus('#ta-reply-text');return false;};
 const act=(fn,selector='#ta-title')=>{if(validWriting()&&fn()!==false)redraw(selector);};
 root.querySelector('[data-ta-recover]')?.addEventListener('click',()=>{if(recoverTravelersArchive(state))redraw();});if(!travelersArchive(state))return;
 const visible=[...new Set([...root.querySelectorAll('[data-ta-source-visible]')].flatMap(el=>el.dataset.taSourceVisible.split(' ')))],r=travelersArchive(state);if(visible.some(id=>!r.sourcesExposed.includes(id))){noteArchiveSources(state,visible);save();}
 root.querySelectorAll('[data-ta-page]').forEach(b=>b.onclick=()=>act(()=>{const page=b.dataset.taPage;if(page==='place-dates'&&!['map','order'].includes(travelersArchive(state).task))setArchiveTask(state,'map');if(page==='sources'&&!['claims','source-choice','limits'].includes(travelersArchive(state).task))setArchiveTask(state,archiveQuestionById(travelersArchive(state).question)?.task||'claims');return setArchivePage(state,page);}));
 root.querySelectorAll('[data-ta-task]').forEach(b=>b.onclick=()=>act(()=>setArchiveTask(state,b.dataset.taTask)));
 root.querySelectorAll('[data-ta-question]').forEach(b=>b.onclick=()=>act(()=>setArchiveQuestion(state,b.dataset.taQuestion),'#ta-current-question'));
 root.querySelectorAll('[data-ta-source]').forEach(b=>b.onclick=()=>act(()=>setArchiveSource(state,b.dataset.taSource),`[data-ta-source="${b.dataset.taSource}"]`));
 root.querySelectorAll('[data-ta-detail]').forEach(b=>b.onclick=()=>act(()=>setArchiveDetail(state,b.dataset.taDetail),`[data-ta-detail="${b.dataset.taDetail}"]`));
 root.querySelectorAll('[data-ta-map]').forEach(b=>b.onclick=()=>act(()=>setArchiveMap(state,...b.dataset.taMap.split(':')),`[data-ta-map="${b.dataset.taMap}"]`));
 root.querySelectorAll('[data-ta-map-check]').forEach(b=>b.onclick=()=>act(()=>checkArchiveMap(state,b.dataset.taMapCheck),`#ta-map-feedback-${b.dataset.taMapCheck}`));
 root.querySelectorAll('[data-ta-order-add]').forEach(b=>b.onclick=()=>act(()=>setArchiveOrder(state,[...travelersArchive(state).order,b.dataset.taOrderAdd]),'.ta-draft-order'));
 root.querySelectorAll('[data-ta-order-remove]').forEach(b=>b.onclick=()=>act(()=>setArchiveOrder(state,travelersArchive(state).order.filter(id=>id!==b.dataset.taOrderRemove)),'.ta-draft-order'));
 root.querySelectorAll('[data-ta-move]').forEach(b=>b.onclick=()=>{const [id,n]=b.dataset.taMove.split(':');act(()=>moveArchiveEvent(state,id,Number(n)),'.ta-draft-order');});
 root.querySelector('[data-ta-order-check]')?.addEventListener('click',()=>act(()=>checkArchiveOrder(state),'#ta-order-feedback'));
 root.querySelectorAll('[data-ta-answer]').forEach(b=>b.onclick=()=>{const [id,choice]=b.dataset.taAnswer.split(':');act(()=>answerArchiveQuestion(state,id,choice),`#ta-answer-feedback-${id}`);});
 root.querySelectorAll('[data-ta-reply-choice]').forEach(b=>b.onclick=()=>{const [field,choice]=b.dataset.taReplyChoice.split(':');act(()=>setArchiveReplyChoice(state,field,choice==='clear'?null:choice),`[data-ta-reply-choice="${b.dataset.taReplyChoice}"]`);});
 root.querySelector('[data-ta-reply-check]')?.addEventListener('click',()=>act(()=>checkArchiveReply(state),'#ta-reply-feedback'));
 root.querySelector('[data-ta-keep]')?.addEventListener('click',()=>act(()=>keepArchiveReply(state),'#ta-kept-status'));
 root.querySelectorAll('[data-ta-support]').forEach(b=>b.onclick=()=>act(()=>useArchiveSupport(state,b.dataset.taSupport,root.dataset.taActiveTask),b.dataset.taSupport==='help'?'#ta-help':b.dataset.taSupport==='example'?'#ta-example':'.ta-support'));
 root.querySelectorAll('[data-ta-reading]').forEach(b=>b.onclick=()=>act(()=>setArchiveReading(state,b.dataset.taReading),`[data-ta-reading="${b.dataset.taReading}"]`));
 root.querySelector('[data-ta-revisit]')?.addEventListener('click',()=>act(()=>revisitArchive(state)));
 root.querySelectorAll('[data-ta-extra-source]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){noteArchiveSources(state,[d.dataset.taExtraSource]);save();}}));
 root.querySelectorAll('[data-ta-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{useArchiveSupport(state,'audio',b.closest('[data-ta-audio]').dataset.taAudio);save();}));
 const input=root.querySelector('#ta-reply-text');input?.addEventListener('input',()=>{writingDirty=true;const text=input.value,result=setArchiveReplyText(state,text);writingError=result.ok?'':result.error;if(result.ok)writingDirty=false;root.querySelector('#ta-writing-count').textContent=`${result.count} / ${ARCHIVE_TEXT_LIMIT} characters`;root.querySelector('#ta-writing-error').textContent=writingError;root.querySelector('[data-ta-keep]').disabled=!result.ok;root.querySelector('[data-ta-reply-check]').disabled=!result.ok;const hear=root.querySelector('[data-ta-audio="reply"] [data-speak]');if(hear)hear.dataset.speak=text||'Your own words are optional. You can also tell someone aloud.';const marker=root.querySelector('#ta-reply-feedback [data-ta-earlier-check]'),r=travelersArchive(state),record=r&&last(r,'reply');if(marker&&record)marker.hidden=same(record.response,{...r.reply,text});if(result.ok)save();});
}
export function travelersArchiveNotes(state){if(!Object.hasOwn(state,'travelersArchive'))return '';return `<details class="panel ta-notes" data-ta-notes><summary>Travelers’ Archive</summary><p>A finite Paris1910 source-comparison visit. Original words are local and ungraded. Source labels, event order, prepared replies, reading reports, support and familiarity stay separate; this is not independent historical-research or reading-level evidence.</p><pre>${esc(JSON.stringify(state.travelersArchive,null,2))}</pre></details>`;}
